-- Legacy rows were generated by the removed market-probability fallback.
-- They have no ticket, review, or evidence references and must not remain
-- available to future decisions, evaluation, or training queries.
DELETE FROM model_predictions
WHERE calculation_version = 'legacy';

ALTER TABLE model_predictions
    ALTER COLUMN validation_status DROP DEFAULT,
    ALTER COLUMN calculation_version DROP DEFAULT;

ALTER TABLE model_predictions
    DROP CONSTRAINT IF EXISTS chk_model_predictions_valid_evidence,
    ADD CONSTRAINT chk_model_predictions_valid_evidence CHECK (
        validation_status <> 'valid'
        OR (
            calculation_version IN ('market_metrics_v2', 'market_metrics_v2_repaired')
            AND odds_snapshot_id IS NOT NULL
            AND model_probability BETWEEN 0 AND 1
            AND market_probability BETWEEN 0 AND 1
            AND break_even_probability BETWEEN 0 AND 1
            AND market_edge IS NOT NULL
            AND breakeven_edge IS NOT NULL
            AND ev IS NOT NULL
        )
    );
